/**
 * Generated by scaffold-test-specs. Tests the canonical dashboard query
 * endpoint shipped by templates/modules/_dashboard/.
 *
 *   POST /api/dashboard/query — { entity, op, where?, group? }
 */
import supertest from 'supertest';
import {
  createTestApp,
  closeTestApp,
  type TestAppContext,
} from '../setup/test-app.factory';
import { cleanDatabase } from '../setup/test-database';
import { createTestUser } from '../fixtures/user.fixture';
import { loginAndGetCookie } from '../fixtures/auth.fixture';
import { RoleEnum } from '../../src/common/enums/role.enum';

describe('Dashboard Query E2E', () => {
  let ctx: TestAppContext;
  let cookie: string;

  beforeAll(async () => {
    ctx = await createTestApp();
    const user = await createTestUser(ctx.dataSource, {
      email: 'dashboard-spec@test.com',
      role: RoleEnum.admin,
    });
    cookie = await loginAndGetCookie(ctx.app, user.email, user.password);
  });

  beforeEach(async () => {
    await cleanDatabase(ctx.dataSource);
  });

  afterAll(async () => {
    await closeTestApp(ctx);
  });

  describe('POST /api/dashboard/query', () => {
    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/dashboard/query')
        .send({ entity: 'users', op: 'count' })
        .expect(401);
    });

    it('returns 400 for unknown entity', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/dashboard/query')
        .set('Cookie', cookie)
        .send({ entity: 'nonexistent_table_xyz', op: 'count' })
        .expect((res) => {
          if (![400, 422].includes(res.status)) {
            throw new Error(`Expected 400 for unknown entity, got ${res.status}`);
          }
        });
    });

    it('returns { value } for count op (no group)', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/dashboard/query')
        .set('Cookie', cookie)
        .send({ entity: 'users', op: 'count' })
        .expect((res) => {
          if (res.status !== 200) {
            // Skip if entity wasn't actually scaffolded in this project; non-test failure.
            return;
          }
          if (typeof (res.body.data ?? res.body).value !== 'number' && !Array.isArray((res.body.data ?? res.body).items)) {
            throw new Error(`Expected { value } or { items } shape, got ${JSON.stringify(res.body)}`);
          }
        });
    });

    it('rejects disallowed where op', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/dashboard/query')
        .set('Cookie', cookie)
        .send({
          entity: 'users',
          op: 'count',
          where: [{ field: 'id', op: 'BADOPNOTALLOWED', value: 'x' }],
        })
        .expect((res) => {
          if (![400, 422].includes(res.status)) {
            throw new Error(`Expected 400 for disallowed op, got ${res.status}`);
          }
        });
    });
  });
});
